1	import type {
2		GameHistoryListResult,
3		GameHistoryRepository,
4	} from "../../domain/game/ports/GameHistoryRepository";
5	import type { GameCardPool, GameHistoryEntry } from "../../domain/game/types";
6	import type { JsonShapeGuard, JsonStore } from "./JsonStore";
7	
8	/**
9	 * Deliberately its own key, never a field on `thai-srs-state`: game history
10	 * is a practice log, not SRS progress, so it must survive an SRS reset and
11	 * stay untouched by `ManageDataUseCase.exportData()`. See CONTEXT.md.
12	 */
13	export const GAME_HISTORY_STORAGE_KEY = "thai-srs-game-history";
14	
15	const GAME_CARD_POOLS: readonly GameCardPool[] = ["script", "vocab"];
16	
17	function isGameCardPool(value: unknown): value is GameCardPool {
18		return (
19			typeof value === "string" &&
20			(GAME_CARD_POOLS as readonly string[]).includes(value)
21		);
22	}
23	
24	/**
25	 * Shallow shape check for one persisted `GameHistoryEntry.summary` — enough
26	 * to reject a corrupt or foreign blob, matching `Validation.ts`'s own
27	 * shallow-not-exhaustive style for the SRS blob.
28	 */
29	function hasGameRoundSummaryShape(value: unknown): boolean {
30		if (value === null || typeof value !== "object") return false;
31		const summary = value as Record<string, unknown>;
32	
33		if (
34			typeof summary.ratingCounts !== "object" ||
35			summary.ratingCounts === null
36		) {
37			return false;
38		}
39		if (typeof summary.ratedCount !== "number") return false;
40		return summary.accuracy === null || typeof summary.accuracy === "number";
41	}
42	
43	/**
44	 * Shallow shape check for one persisted `GameHistoryEntry` — enough to
45	 * reject a corrupt or foreign blob, not a full domain-validity check.
46	 */
47	function isGameHistoryEntry(value: unknown): value is GameHistoryEntry {
48		if (value === null || typeof value !== "object") return false;
49		const entry = value as Record<string, unknown>;
50	
51		return (
52			typeof entry.id === "string" &&
53			typeof entry.playedAt === "string" &&
54			typeof entry.itemCount === "number" &&
55			Array.isArray(entry.pools) &&
56			entry.pools.every(isGameCardPool) &&
57			hasGameRoundSummaryShape(entry.summary)
58		);
59	}
60	
61	/** Shape guard for the `JsonStore<GameHistoryEntry[]>` this repository is built over. */
62	export const isGameHistoryEntryArray: JsonShapeGuard<GameHistoryEntry[]> = (
63		value,
64	): value is GameHistoryEntry[] =>
65		Array.isArray(value) && value.every(isGameHistoryEntry);
66	
67	/**
68	 * `GameHistoryRepository` over a `JsonStore<GameHistoryEntry[]>` — a
69	 * corrupt store maps to `{status:"unavailable"}`, an empty one to
70	 * `{status:"ok", entries:[]}`, and listing sorts most-recent-first.
71	 */
72	export class StorageGameHistoryRepository implements GameHistoryRepository {
73		constructor(private readonly store: JsonStore<GameHistoryEntry[]>) {}
74	
75		list(): GameHistoryListResult {
76			const result = this.store.load();
77			if (result.status === "corrupt") return { status: "unavailable" };
78			if (result.status === "empty") return { status: "ok", entries: [] };
