1	import { describe, expect, it } from "vitest";
2	import type { CardRepository } from "../../ports/CardRepository";
3	import { consonants } from "../../script/data/symbols";
4	import { ScriptPropertyCard } from "../../script/entities/ScriptPropertyCard";
5	import type { CardPool } from "../../shared/CardPool";
6	import type { PropertyType } from "../../shared/types";
7	import { SrsSchedule } from "../../srs/value-objects/SrsSchedule";
8	import type {
9		GameCardPool,
10		GameItemContent,
11		GameItemSource,
12		RandomSource,
13	} from "../types";
14	import { GameItemSelectionService } from "./GameItemSelectionService";
15	import { SymbolGameItemSource } from "./SymbolGameItemSource";
16	
17	function symbolContent(character: string, audioUrl?: string): GameItemContent {
18		return {
19			kind: "symbol",
20			symbolCharacter: character,
21			promptText: character,
22			correctAnswer: `name of ${character}`,
23			audioUrl,
24		};
25	}
26	
27	function sourceOf(
28		pool: GameCardPool,
29		content: readonly GameItemContent[],
30	): GameItemSource {
31		return { pool, eligibleContent: () => [...content] };
32	}
33	
34	function scripted(values: readonly number[]): RandomSource {
35		let index = 0;
36		return () => values[index++ % values.length] as number;
37	}
38	
39	const FIVE = ["1", "2", "3", "4", "5"].map((character) =>
40		symbolContent(character, `/audio/${character}.mp3`),
41	);
42	
43	const SCRIPT_ONLY = { pools: ["script"] as const };
44	
45	describe("GameItemSelectionService", () => {
46		it("returns exactly the requested count, one per distinct symbol", () => {
47			const service = new GameItemSelectionService([sourceOf("script", FIVE)]);
48	
49			const round = service.selectRound(
50				{ ...SCRIPT_ONLY, itemCount: 3 },
51				// A source that always names the first of what remains: only
52				// removing each drawn item keeps the three distinct.
53				scripted([0.0]),
54			);
55	
56			expect(round).toHaveLength(3);
57			expect(new Set(round.map((item) => item.symbolCharacter)).size).toBe(3);
58		});
59	
60		it("returns every eligible item when more are requested than exist", () => {
61			const service = new GameItemSelectionService([sourceOf("script", FIVE)]);
62	
63			const round = service.selectRound(
64				{ ...SCRIPT_ONLY, itemCount: 50 },
65				scripted([0.3, 0.8, 0.1]),
66			);
67	
68			expect(round).toHaveLength(5);
69			expect(new Set(round.map((item) => item.symbolCharacter)).size).toBe(5);
70		});
71	
72		it("returns an empty round when nothing is eligible", () => {
73			const service = new GameItemSelectionService([sourceOf("script", [])]);
74	
75			expect(
76				service.selectRound({ ...SCRIPT_ONLY, itemCount: 5 }, scripted([0.5])),
77			).toEqual([]);
78		});
79	
80		it("assigns the exact direction sequence a seeded source dictates", () => {
81			const service = new GameItemSelectionService([sourceOf("script", FIVE)]);
82	
83			// Draws: 0.0 of 5 -> "1"; 0.75 of the remaining 4 -> "5";
84			// 0.5 of the remaining 3 -> "3". Then one roll per item:
85			// 0.1 < 0.5 -> dictation, 0.9 -> reading, 0.49 < 0.5 -> dictation.
86			const round = service.selectRound(
87				{ ...SCRIPT_ONLY, itemCount: 3 },
88				scripted([0.0, 0.75, 0.5, 0.1, 0.9, 0.49]),
89			);
90	
91			expect(
92				round.map((item) => [item.symbolCharacter, item.challengeDirection]),
93			).toEqual([
94				["1", "dictation"],
95				["5", "reading"],
96				["3", "dictation"],
97			]);
98		});
99	
100		it("treats a symbol with cards under several properties as one item", () => {
101			const character = (consonants[0] as (typeof consonants)[number]).character;
102			const cards = (
103				["recognition", "class", "initialSound"] as PropertyType[]
104			).map(
105				(property, index) =>
106					new ScriptPropertyCard(
107						`card-${index}`,
108						`question ${index}`,
109						`answer ${index}`,
110						[],
111						SrsSchedule.initial(),
112						character,
113						property,
114						1,
115					),
116			);
117			const repository: CardRepository = {
118				findById: () => null,
119				findDue: () => [],
120				findAll: (pool: CardPool) => (pool === "script" ? [...cards] : []),
121				save: () => {},
122				saveAll: () => {},
123				remove: () => {},
124			};
125			const service = new GameItemSelectionService([
126				new SymbolGameItemSource(repository),
127			]);
128	
129			const round = service.selectRound(
130				{ ...SCRIPT_ONLY, itemCount: 3 },
131				scripted([0.0, 0.5]),
132			);
133	
134			expect(
135				round.filter((item) => item.symbolCharacter === character),
136			).toHaveLength(1);
137		});
138	
139		it("never assigns dictation to a symbol with no audio", () => {
140			const service = new GameItemSelectionService([
141				sourceOf("script", [
142					symbolContent("silent"),
143					symbolContent("loud", "/audio/loud.mp3"),
144				]),
145			]);
146			const rng = scripted([0.0, 0.13, 0.27, 0.41, 0.55, 0.68, 0.82, 0.96]);
147			const directions = new Set<string>();
148	
149			for (let round = 0; round < 200; round++) {
150				for (const item of service.selectRound(
151					{ ...SCRIPT_ONLY, itemCount: 2 },
152					rng,
153				)) {
154					if (item.symbolCharacter === "silent") {
155						expect(item.challengeDirection).toBe("reading");
156					} else {
157						directions.add(item.challengeDirection);
158					}
159				}
160			}
161	
162			// The run really did vary — otherwise "always reading" proves nothing.
163			expect([...directions].sort()).toEqual(["dictation", "reading"]);
164		});
165	
166		it("clamps and floors a degenerate requested count", () => {
167			const service = new GameItemSelectionService([sourceOf("script", FIVE)]);
168			const cases: ReadonlyArray<readonly [number, number]> = [
169				[0, 0],
170				[-1, 0],
171				[2.5, 2],
172				[Number.NaN, 0],
173				[1e9, 5],
174			];
175	
176			for (const [requested, expected] of cases) {
177				const startedAt = Date.now();
178				const round = service.selectRound(
179					{ ...SCRIPT_ONLY, itemCount: requested },
180					scripted([0.2, 0.4, 0.6, 0.8]),
181				);
182				expect(round).toHaveLength(expected);
183				expect(Date.now() - startedAt).toBeLessThan(50);
184			}
185		});
186	
187		it("draws only from the pools the round asks for", () => {
188			const service = new GameItemSelectionService([
189				sourceOf("script", FIVE),
190				sourceOf("vocab", [symbolContent("unused", "/audio/unused.mp3")]),
191			]);
